  3	namespace Modules\AI\Domain\Defense;
  4	
  5	/**
  6	 * The anti-ballistic missile policy: what a Missile Silo stores, what one missile
  7	 * costs, and the stats a defensive decision budgets against.
  8	 *
  9	 * Every number lives in resources/behavior/def-ipm.yaml, so the defensive budget
 10	 * is retuned by a modder editing that file rather than by editing PHP.
 11	 */
 12	final class AntiBallisticMissile
 13	{
 14	    private const POLICY_FILE = '/resources/behavior/def-ipm.yaml';
 15	    private const ENTRY_SEPARATOR = ':';
 16	    private const COMMENT_PREFIX = '#';
 17	
 18	    private const KEY_ABM_PER_SILO_LEVEL = 'abm_per_missile_silo_level';
 19	    private const KEY_IPM_PER_SILO_LEVEL = 'ipm_per_missile_silo_level';
 20	    private const KEY_IPM_TO_ABM_CAPACITY_RATIO = 'ipm_to_abm_capacity_ratio';
 21	    private const KEY_COST_METAL = 'abm_cost_metal';
 22	    private const KEY_COST_CRYSTAL = 'abm_cost_crystal';
 23	    private const KEY_COST_DEUTERIUM = 'abm_cost_deuterium';
 24	    private const KEY_INTEGRITY = 'abm_integrity';
 25	    private const KEY_SHIELD = 'abm_shield';
 26	    private const KEY_WEAPON = 'abm_weapon';
 27	    private const KEY_PREREQUISITE_MISSILE_SILO_LEVEL = 'abm_prerequisite_missile_silo_level';
 28	
 29	    /** @param array<string, int|string> $entries */
 30	    private function __construct(private readonly array $entries)
 31	    {
 32	    }
 33	
 34	    public static function policy(): self
 35	    {
 36	        $path = dirname(__DIR__, 3) . self::POLICY_FILE;
 37	
 38	        return new self(self::parse((string) file_get_contents($path)));
 39	    }
 40	
 41	    /**
 42	     * A Missile Silo level stores ten anti-ballistic missiles, so the silo level
 43	     * is the cap on how many an account may keep at once.
 44	     */
 45	    public function abmCapacity(int $missileSiloLevel): int
 46	    {
 47	        return $this->entry(self::KEY_ABM_PER_SILO_LEVEL) * $missileSiloLevel;
 48	    }
 49	
 50	    public function ipmCapacity(int $missileSiloLevel): int
 51	    {
 52	        return $this->entry(self::KEY_IPM_PER_SILO_LEVEL) * $missileSiloLevel;
 53	    }
 54	
 55	    /** Interplanetary missiles storable per anti-ballistic missile storable, as stated. */
 56	    public function ipmToAbmCapacityRatio(): string
 57	    {
 58	        return $this->text(self::KEY_IPM_TO_ABM_CAPACITY_RATIO);
 59	    }
 60	
 61	    /** @return array{metal: int, crystal: int, deuterium: int} */
 62	    public function cost(): array
 63	    {
 64	        return [
 65	            'metal' => $this->entry(self::KEY_COST_METAL),
 66	            'crystal' => $this->entry(self::KEY_COST_CRYSTAL),
 67	            'deuterium' => $this->entry(self::KEY_COST_DEUTERIUM),
 68	        ];
 69	    }
 70	
 71	    public function prerequisiteMissileSiloLevel(): int
 72	    {
 73	        return $this->entry(self::KEY_PREREQUISITE_MISSILE_SILO_LEVEL);
 74	    }
 75	
 76	    public function integrity(): int
 77	    {
 78	        return $this->entry(self::KEY_INTEGRITY);
 79	    }
 80	
 81	    public function shield(): int
 82	    {
 83	        return $this->entry(self::KEY_SHIELD);
 84	    }
 85	
 86	    public function weapon(): int
 87	    {
 88	        return $this->entry(self::KEY_WEAPON);
 89	    }
 90	
 91	    private function entry(string $key): int
 92	    {
 93	        return (int) $this->entries[$key];
 94	    }
 95	
 96	    private function text(string $key): string
 97	    {
 98	        return (string) $this->entries[$key];
 99	    }
100	
101	    /**
102	     * The policy file is flat `key: value` YAML so a modder can read and edit it,
103	     * and the module parses it without pulling in a YAML parser.
104	     *
105	     * @return array<string, int|string>
106	     */
107	    private static function parse(string $contents): array
108	    {
109	        $entries = [];
110	
111	        foreach (preg_split('/\R/', $contents) as $line) {
112	            $line = trim($line);
113	
114	            if ($line === '' || str_starts_with($line, self::COMMENT_PREFIX)) {
115	                continue;
116	            }
117	
118	            if (! str_contains($line, self::ENTRY_SEPARATOR)) {
119	                continue;
120	            }
121	
122	            [$key, $value] = array_map('trim', explode(self::ENTRY_SEPARATOR, $line, 2));
123	
124	            $entries[$key] = is_numeric($value) ? (int) $value : $value;
125	        }
126	
127	        return $entries;
128	    }
129	}

