  8	use OGame\Models\Message;
  9	use OGame\Models\User;
 10	use OGame\Services\PlayerService;
 11	
 12	/**
 13	 * Interplanetary missiles are how a player thins a wall before the fleet arrives, so a planet that holds
 14	 * missiles and has a fresh report on a defended target inside the missile range fires them. The range,
 15	 * the missile count and the target's standing defence are the host's; the planner only asks.
 16	 */
 17	class QueueableMissilePlanner
 18	{
 19	    /** The host's machine name for the missile object, the one catalogue name the host's own mission also reads. */
 20	    private const MISSILE = 'interplanetary_missile';
 21	
 22	    private const REPORT_FRESH_HOURS = 12;
 23	
 24	    /** A wall thinner than this is not worth a missile each. */
 25	    private const MIN_DEFENCE_UNITS = 20;
 26	
 27	    public function __construct(private PlayerServiceFactory $playerServiceFactory)
 28	    {
 29	    }
 30	
 31	    public function plan(int $playerId): ?QueueableMissile
 32	    {
 33	        if (!AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->exists()) {
 34	            return null;
 35	        }
 36	
 37	        if (!User::query()->whereKey($playerId)->exists()) {
 38	            return null;
 39	        }
 40	
 41	        $player = $this->playerServiceFactory->make($playerId, true);
 42	        $range = $player->getMissileRange();
 43	        if ($range < 1) {
 44	            return null;
 45	        }
 46	
 47	        $reportIds = Message::query()
 48	            ->where('user_id', $playerId)
 49	            ->whereNotNull('espionage_report_id')
 50	            ->where('created_at', '>=', now()->subHours(self::REPORT_FRESH_HOURS))
 51	            ->pluck('espionage_report_id');
 52	        if ($reportIds->isEmpty()) {
 53	            return null;
 54	        }
 55	
 56	        $reports = EspionageReport::query()->whereIn('id', $reportIds)->orderByDesc('id')->get();
 57	
 58	        foreach ($player->planets->all() as $planet) {
 59	            $missiles = $planet->getObjectAmount(self::MISSILE);
 60	            if ($missiles < 1) {
 61	                continue;
 62	            }
 63	
 64	            $origin = $planet->getPlanetCoordinates();
 65	            $best = null;
 66	            $bestWall = 0;
 67	
 68	            foreach ($reports as $report) {
 69	                if ((int) $report->planet_galaxy !== $origin->galaxy
 70	                    || abs((int) $report->planet_system - $origin->system) > $range
 71	                    || (int) $report->planet_user_id === $playerId) {
 72	                    continue;
 73	                }
 74	
 75	                $wall = (int) array_sum($report->defense ?? []);
 76	                // The host's own interceptor is not a wall: the missiles of the target's silo answer 1:1 elsewhere.
 77	                if ($wall < self::MIN_DEFENCE_UNITS || $wall <= $bestWall || $this->shielded($player, (int) $report->planet_user_id)) {
 78	                    continue;
 79	                }
 80	
 81	                $best = $report;
 82	                $bestWall = $wall;
 83	            }
 84	
 85	            if ($best === null) {
 86	                continue;
 87	            }
 88	
 89	            return app()->makeWith(QueueableMissile::class, [
 90	                'originPlanetId' => $planet->getPlanetId(),
 91	                'targetGalaxy' => (int) $best->planet_galaxy,
 92	                'targetSystem' => (int) $best->planet_system,
 93	                'targetPosition' => (int) $best->planet_position,
 94	                'targetType' => (int) $best->planet_type,
 95	                'missiles' => $missiles,
 96	            ]);
 97	        }
 98	
 99	        return null;
100	    }
101	
102	    private function shielded(PlayerService $player, int $targetUserId): bool
103	    {
104	        if ($targetUserId <= 0 || !User::query()->whereKey($targetUserId)->exists()) {
105	            return true;
106	        }
107	
108	        return $this->playerServiceFactory->make($targetUserId, true)->isNewbie($player);
109	    }
110	}

