  4	
  5	use Exception;
  6	use Illuminate\Support\Facades\DB;
  7	use Modules\AI\Contracts\QueueAiUnits;
  8	use Modules\AI\Domain\Decision\DefenseCompositionPlanner;
  9	use Modules\AI\Enums\AiQueueActionReason;
 10	use Modules\AI\Support\AiActionResult;
 11	use OGame\Factories\PlanetServiceFactory;
 12	use OGame\GameObjects\Models\Enums\GameObjectType;
 13	use OGame\Models\Planet;
 14	use OGame\Models\UnitQueue;
 15	use OGame\Services\ObjectService;
 16	use OGame\Services\PlayerGameStateService;
 17	use OGame\Services\PlayerService;
 18	use OGame\Services\UnitQueueService;
 19	
 20	/**
 21	 * Module-owned adapter over the normal OGameX unit queue.
 22	 *
 23	 * The decision is the module's; the queue, its requirements and its prices are the host's. The host
 24	 * service silently returns when the amount is unaffordable, so the planner must have already asked
 25	 * what the planet can pay for -- this adapter only refuses what the host would never accept as a
 26	 * unit, and reports whether a queue row actually appeared.
 27	 */
 28	class QueueAiUnitsAction implements QueueAiUnits
 29	{
 30	    public function __construct(
 31	        private PlayerGameStateService $playerGameStateService,
 32	        private PlanetServiceFactory $planetServiceFactory,
 33	        private UnitQueueService $unitQueueService,
 34	    ) {
 35	    }
 36	
 37	    public function handle(int $playerId, int $planetId, int $unitId, int $amount): AiActionResult
 38	    {
 39	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 40	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 41	        }
 42	
 43	        if ($amount < 1) {
 44	            return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
 45	        }
 46	
 47	        try {
 48	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 49	
 50	            if ($player->isBanned()) {
 51	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 52	            }
 53	            if ($player->isInVacationMode()) {
 54	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 55	            }
 56	
 57	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 58	            $unit = ObjectService::getObjectById($unitId);
 59	            if ($unit->type !== GameObjectType::Ship && $unit->type !== GameObjectType::Defense) {
 60	                return AiActionResult::rejected(AiQueueActionReason::NotAUnit);
 61	            }
 62	
 63	            // The host's add() returns silently, with nothing queued, for a unit whose requirements or
 64	            // character class the planet does not meet: ask both first so the refusal has a name
 65	            // instead of reading as queue_not_created.
 66	            if (!ObjectService::objectRequirementsMet($unit->machine_name, $planet) || !ObjectService::objectCharacterClassMet($unit->machine_name, $planet)) {
 67	                return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
 68	            }
 69	
 70	            if ($unit->type === GameObjectType::Defense) {
 71	                return $this->queueDefence($player, $planetId, $unitId, $amount);
 72	            }
 73	
 74	            // Priced a session ago: the host's add() silently ignores a batch the planet can no longer
 75	            // pay for whole, so the order is what it can pay for now, as the defence path does.
 76	            $amount = min($amount, ObjectService::getObjectMaxBuildAmount($unit->machine_name, $planet, true));
 77	            if ($amount < 1) {
 78	                return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
 79	            }
 80	
 81	            $this->unitQueueService->add($planet, $unitId, $amount);
 82	            $queueId = UnitQueue::query()
 83	                ->where('planet_id', $planetId)
 84	                ->where('object_id', $unitId)
 85	                ->where('processed', 0)
 86	                ->latest('id')
 87	                ->value('id');
 88	
 89	            return $queueId === null ? AiActionResult::rejected(AiQueueActionReason::QueueNotCreated) : AiActionResult::queued($queueId);
 90	        } catch (Exception $exception) {
 91	            return AiActionResult::rejected($exception->getMessage());
 92	        }
 93	    }
 94	
 95	    /**
 96	     * The defence order, trimmed to what the planet's standing wall has left of the behaviour file's
 97	     * ceiling, with the reading and the writing under one lock.
 98	     *
 99	     * The planner refuses a wall at the ceiling, but a session backlog runs several intents on the
100	     * same planet at once and each reads the same shortfall before any of them reaches the yard, so
101	     * the ceiling is applied where the units are written. The planet row is locked across the read
102	     * and the write, so a worker that waited sees what the one before it bought (live 2 Oct 2026: a
103	     * planet the file caps at 20,000 units held 24,900, one batch per concurrent worker).
104	     */
105	    private function queueDefence(PlayerService $player, int $planetId, int $unitId, int $amount): AiActionResult
106	    {
107	        return DB::transaction(function () use ($player, $planetId, $unitId, $amount): AiActionResult {
108	            DB::table('planets')->where('id', $planetId)->lockForUpdate()->value('id');
109	
110	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
111	            $remaining = app(DefenseCompositionPlanner::class)->remainingCeiling($planet);
112	            $amount = $remaining === null ? $amount : min($amount, max(0, $remaining));
113	            // The order was priced a session ago and other work on this planet has spent the balance
114	            // since: the host's add() returns silently for a batch it cannot pay for whole, so the wall
115	            // never appeared while the planet stayed naked (live 2 Oct 2026: 4 x QueueUnits refused with
116	            // queue_not_created). What this planet can pay for now is the order.
117	            $amount = min($amount, ObjectService::getObjectMaxBuildAmount(ObjectService::getObjectById($unitId)->machine_name, $planet, true));
118	            if ($amount < 1) {
119	                return AiActionResult::rejected(AiQueueActionReason::NothingQueueable);
120	            }
121	
122	            $this->unitQueueService->add($planet, $unitId, $amount);
123	            $queueId = UnitQueue::query()
124	                ->where('planet_id', $planetId)
125	                ->where('object_id', $unitId)
126	                ->where('processed', 0)
127	                ->latest('id')
128	                ->value('id');
129	
130	            return $queueId === null ? AiActionResult::rejected(AiQueueActionReason::QueueNotCreated) : AiActionResult::queued($queueId);
131	        });
132	    }
133	}

