  201	        return is_numeric($units) && (int) $units > 0 ? (int) $units : null;
  202	    }
  203	
  204	    /**
  205	     * The defence units a planet already holds, built or waiting in the yard: what is left of the
  206	     * ceiling. Ships in the same queue do not count, because the ceiling is about the wall.
  207	     *
  208	     * @param  array<string, int>  $pending
  209	     */
  210	    private function heldDefenseUnits(UnitCollection $current, array $pending): int
  211	    {
  212	        $total = 0;
  213	
  214	        foreach ($this->defenceObjectsByMachineName() as $machineName => $object) {
  215	            $total += $current->getAmountByMachineName($machineName) + ($pending[$machineName] ?? 0);
  216	        }
  217	
  218	        return $total;
  219	    }
  220	
  221	    /**
  222	     * The doctrine the wall moves to once it outgrows the one it started in.
  223	     *
  224	     * The handover is the doctrine's structured `swap_after: {doctrine, anchor_count}`, so rewording
  225	     * the quoted `stop_rule` sentence beside it cannot change which doctrine the wall moves to.
  226	     *
  227	     * @param  array<string, array{anchor: array{unit: string, count: int}, ratio: array<string, int>, swap_after?: array{doctrine: string, anchor_count: int}}>  $doctrines
  228	     * @param  array<string, UnitObject>  $defenceObjects
  229	     */
  230	    private function afterStopRule(array $doctrines, array $defenceObjects, string $key, PlanetService $planet): string
  231	    {
  232	        $swap = $doctrines[$key]['swap_after'] ?? null;
  233	        if (!is_array($swap) || !isset($swap['doctrine'], $swap['anchor_count'])) {
  234	            return $key;
  235	        }
  236	
  237	        $anchor = $this->resolveUnit($doctrines[$key]['anchor']['unit'], $defenceObjects);
  238	        $wall = $planet->getDefenseUnits()->getAmountByMachineName($anchor->machine_name);
  239	
  240	        return $wall > (int) $swap['anchor_count'] ? (string) $swap['doctrine'] : $key;
  241	    }
  242	
  243	    /**
  244	     * What one anchor unit of this doctrine is worth, from the host's own prices: the anchor itself
  245	     * plus its share of every ratio unit.
  246	     *
  247	     * The ratio is stated per anchor count, so a wall of scale S holds S anchors and ratio/100 of
  248	     * each other unit per anchor -- the same arithmetic the targets below are derived with. Pricing
  249	     * it here is what lets a need stated in value become a scale without the evaluator knowing a
  250	     * single price or ratio.
  251	     *
  252	     * @param  array{anchor: array{unit: string, count: int}, ratio: array<string, int>}  $doctrine
  253	     * @param  array<string, UnitObject>  $defenceObjects
  254	     */
  255	    private function layerValue(UnitObject $anchor, array $doctrine, array $defenceObjects): float
  256	    {
  257	        $ratioValue = 0.0;
  258	        foreach ($doctrine['ratio'] as $name => $ratio) {
  259	            $unit = $this->resolveUnit($name, $defenceObjects);
  260	            $ratioValue += $ratio * $this->metalEquivalent(ObjectService::getObjectRawPrice($unit->machine_name));
  261	        }
  262	
  263	        return $this->metalEquivalent(ObjectService::getObjectRawPrice($anchor->machine_name))
  264	            + $ratioValue / (int) $doctrine['anchor']['count'];
  265	    }
  266	
  267	    private function metalEquivalent(Resources $resources): float
  268	    {
  269	        return $resources->metal->get()
  270	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
  271	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
  272	    }
  273	
  274	    /**
  275	     * How many of a unit this planet can put in the yard now, or 0 when the host would not take it.
  276	     *
  277	     * Requirements and character class are the host's; the amount the planet can pay for is the
  278	     * host's own price arithmetic, so the planner never prices a unit itself.
  279	     */
  280	    private function queueableAmount(PlanetService $planet, UnitObject $unit): int
